import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    d = np.nan_to_num(np.asarray(dist_m, dtype=float), nan=1e6, posinf=1e6, neginf=0.0)
    d = np.maximum(d, 0.0)
    f = np.nan_to_num(np.asarray(fits, dtype=float), nan=0.0, posinf=1.0, neginf=0.0)
    score = (1.0 / (1.0 + d)) * (1.0 + 0.2 * np.clip(f, 0.0, 1.0))
    return np.clip(score, 1e-12, 1e12)
```
